#!/usr/bin/env python3
"""Generates docs/DATA_MODEL_DETAILED.md from the contract files (single source of truth: the JSON)."""
import glob, json, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
L = lambda *p: json.load(open(os.path.join(ROOT, *p), encoding="utf-8"))
def flat(s, root, path="", req=True, out=None):
    out = [] if out is None else out
    if "$ref" in s: s = root["$defs"][s["$ref"][8:]]
    if "oneOf" in s:
        out.append((path or "$", "oneOf(" + str(len(s["oneOf"])) + " variants)", "", "")); 
        for i, v in enumerate(s["oneOf"]): flat(v, root, path + f"<v{i+1}>", req, out)
        return out
    t = s.get("type"); t = "|".join(t) if isinstance(t, list) else t
    note = []
    for k in ("const", "enum", "pattern", "minimum", "maximum", "minLength", "maxLength", "minItems", "maxItems"):
        if k in s: note.append(f"{k}={json.dumps(s[k], ensure_ascii=False)}")
    if s.get("x-sorted"): note.append("sorted")
    if path: out.append((path, t or "", "yes" if req else "no", "; ".join(note)))
    if t == "object" or "properties" in s:
        rq = set(s.get("required", []))
        for k, v in s.get("properties", {}).items(): flat(v, root, f"{path}.{k}" if path else k, k in rq, out)
    if "items" in s: flat(s["items"], root, path + "[]", True, out)
    return out
def table(rows):
    o = "| field | type | required | constraints |\n|---|---|---|---|\n"
    for r in rows: o += "| `%s` | %s | %s | %s |\n" % tuple(str(x).replace("|", "\\|") for x in r)
    return o
ev = L("contracts/catalogs/event-catalog.v3.json"); fc = L("contracts/catalogs/fact-catalog.v2.json"); api = L("contracts/api/api-contract.v3.json"); az = L("contracts/api/authorization-matrix.v3.json")
o = ["# DATA_MODEL_DETAILED — CL06.3\n", "Generated by `tools/build_docs.py` from `contracts/` (the JSON files are normative; this document is a rendering). Schema dialect: JSON Schema 2020-12 subset (type, const, enum, pattern, min/max, minLength/maxLength, minItems/maxItems, uniqueItems, properties, required, additionalProperties:false, items, oneOf, $ref, plus the custom keyword `x-sorted`).\n",
     "## 1. Layers\n", "1. **Events** (append-only, hash-chained per `stream_id`). Envelope v3 + typed payload. Source of facts.\n2. **Entities** (declared records with an explicit version chain per `entity_id`; not run through the movement verifier).\n3. **Facts** (derived by a future verifier from events; the contract fixes their shape, catalog and evidence rules, not their computation).\n4. **Evolution** (`evolution.published`, `progress-series`): descriptive series built only from reviewed facts under the comparability rules.\n",
     "## 2. Envelope v3 (all 19 event types)\n"]
s = L("contracts/schemas/events/cycle.accepted.schema.json")
env = [r for r in flat(s, s) if r[0].count(".") == 0 or r[0].split(".")[0] in ("actor", "scope", "source")]
o.append(table([r for r in env if not r[0].startswith("payload")]))
o.append("\nEnvelope rules (see `event-catalog.v3.json` `rules`): `execution_mode` is `not_applicable` outside session streams and one of camera/simulation/report_only/not_applicable inside; `session.started` is seq 1 and its `source_mode` equals the envelope `execution_mode`; `origin_ref` is required for `experimental_capture` and `imported_v1`; `data_origin=live` is rejected while the real-data gate is closed (PD-05). Execution mode (how the data was captured) is distinct from data origin (what the data is): PD-03, DL-11.\n")
o.append("\n## 3. Event types\n")
for t, m in ev["types"].items():
    s = L("contracts/schemas/events/%s.schema.json" % t)
    rows = [r for r in flat(s, s) if r[0].startswith("payload")]
    o.append(f"### `{t}`\n\nStream `{m['stream']}` · authored by `{m['authored']}` · actors {m['actors']} · sources {m['sources']} · scope required {m['scope']['required']} forbidden {m['scope']['forbidden']} · algorithm_version {m['algorithm']} · t_mono_ms {m['mono']}" + (" · **new in v3**" if t in ev["added_in_v3"] else "") + (f" · changed: {ev['changed_in_v3'][t]}" if t in ev["changed_in_v3"] else "") + "\n\n" + table(rows) + "\n")
o.append("## 4. Entities\n")
for p in sorted(glob.glob(os.path.join(ROOT, "contracts/schemas/entities/*.schema.json"))):
    s = json.load(open(p, encoding="utf-8")); n = os.path.basename(p)[:-12]
    o.append(f"### `{n}`\n\n" + table(flat(s, s)) + "\n")
o.append("Entity integrity: `hash = sha256(canonical(entity without hash))`; `version` 1 has `prev_hash` null; version n>1 has `prev_hash` = hash of version n-1; `entity_id` prefix per type (p, t, cl, fa, gl, en, ra, im, dr). Authors are `therapist` or `participant` only (PD-08).\n")
o.append("\n## 5. Fact catalog v2\n\n| fact | name | definition_version | summary_eligible | experimental | limitations |\n|---|---|---|---|---|---|\n")
for k, m in fc["types"].items(): o.append(f"| {k} | {m['name']} | {m['definition_version']} | {m.get('summary_eligible')} | {m.get('experimental', False)} | {m.get('limitations', '')} |\n")
o.append("\nF07 is intentionally absent (as in v1). Changed in v2: F01 (handedness semantics, PD-04) and F05 (semantic note). F02, F03, F04, F06, F08, F09 are unchanged in definition (definition_version 1). F10 is new, experimental, and not eligible for a summary.\n")
o.append("\n## 6. API v3 (%d endpoints)\n\n| id | method | path | roles | status | requirements |\n|---|---|---|---|---|---|\n" % len(api["endpoints"]))
for e in api["endpoints"]: o.append(f"| {e['id']} | {e['method']} | `{e['path']}` | {', '.join(e['roles'])} | {e['status']} | {', '.join(e['prd_requirements'])} |\n")
o.append("\n## 7. Authorization matrix (%d rows)\n\n| resource | action | participant | therapist | condition |\n|---|---|---|---|---|\n" % len(az["rows"]))
for r in az["rows"]: o.append(f"| {r['resource']} | {r['action']} | {r['participant']} | {r['therapist']} | {r.get('condition','')} |\n")
o.append("\nOnly `participant` and `therapist` exist. `caregiver` and `supervisor` are rejected with `ROLE_NOT_ALLOWED` (PD-08).\n")
open(os.path.join(ROOT, "docs/DATA_MODEL_DETAILED.md"), "w", encoding="utf-8").write("".join(o)); print("ok", sum(len(x) for x in o))
